<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<algorithm>
#include<queue>
using namespace std;

const int MAXN=15;
const int MAXM=100005;
const int INF=1000000000;
const int dx[4]={0,0,-1,1};
const int dy[4]={1,-1,0,0};

char A[MAXN][MAXN], B[MAXN][MAXN];
int n, Tlim, zx, zy, S, T, tot;
int id[MAXN][MAXN], dFromZ[MAXN][MAXN], seen[MAXN][MAXN];
int queArr[MAXM], disLevel[MAXN*MAXN*2+5];
int head[MAXN*MAXN*2+5], edgeCnt=1;
struct Edge { int to, next, cap; } edges[MAXM];
int dFromCell[MAXN][MAXN];
struct Pt { int x, y; };

inline bool valid(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n || seen[x][y] || A[x][y] < '0' || A[x][y] > '9') return 0;
    return 1;
}

void addEdge(int u, int v, int c) {
    edges[++edgeCnt].to = v; edges[edgeCnt].cap = c; edges[edgeCnt].next = head[u]; head[u] = edgeCnt;
    edges[++edgeCnt].to = u; edges[edgeCnt].cap = 0; edges[edgeCnt].next = head[v]; head[v] = edgeCnt;
}

void bfsFromZ() {
    memset(dFromZ, 60, sizeof(dFromZ));
    memset(seen, 0, sizeof(seen));
    queue<Pt> q;
    dFromZ[zx][zy] = 0;
    seen[zx][zy] = 1;
    q.push(Pt{zx, zy});
    while (!q.empty()) {
        Pt cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (valid(nx, ny)) {
                dFromZ[nx][ny] = dFromZ[cur.x][cur.y] + 1;
                seen[nx][ny] = 1;
                q.push(Pt{nx, ny});
            }
        }
    }
}

void buildLinks(int sx, int sy, int node) {
    memset(seen, 0, sizeof(seen));
    memset(dFromCell, 60, sizeof(dFromCell));
    queue<Pt> q;
    seen[sx][sy] = 1;
    dFromCell[sx][sy] = 0;
    q.push(Pt{sx, sy});
    while (!q.empty()) {
        Pt cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (valid(nx, ny)) {
                dFromCell[nx][ny] = dFromCell[cur.x][cur.y] + 1;
                seen[nx][ny] = 1;
                if (dFromCell[nx][ny] < dFromZ[nx][ny]) q.push(Pt{nx, ny});
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (dFromCell[i][j] <= Tlim && B[i][j] > '0' && B[i][j] <= '9' && dFromCell[i][j] <= dFromZ[i][j])
                addEdge(node, id[i][j] + tot, INF);
}

bool bfsLevel() {
    memset(disLevel, -1, sizeof(disLevel));
    queue<int> q;
    disLevel[S] = 0;
    q.push(S);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i; i = edges[i].next) {
            int v = edges[i].to;
            if (edges[i].cap > 0 && disLevel[v] == -1) {
                disLevel[v] = disLevel[u] + 1;
                q.push(v);
            }
        }
    }
    return disLevel[T] != -1;
}

int dfsFlow(int u, int flow) {
    if (u == T) return flow;
    int usedFlow = 0;
    for (int i = head[u]; i && flow; i = edges[i].next) {
        int v = edges[i].to;
        if (edges[i].cap > 0 && disLevel[v] == disLevel[u] + 1) {
            int ret = dfsFlow(v, min(edges[i].cap, flow));
            if (ret) {
                edges[i].cap -= ret;
                edges[i ^ 1].cap += ret;
                flow -= ret;
                usedFlow += ret;
            }
        }
    }
    if (!usedFlow) disLevel[u] = INF;
    return usedFlow;
}

int maxflow() {
    int ans = 0;
    while (bfsLevel()) {
        int f;
        while ((f = dfsFlow(S, INF))) ans += f;
    }
    return ans;
}

int main() {
    scanf("%d%d", &n, &Tlim);
    for (int i = 0; i < n; ++i) scanf("%s", A[i]);
    for (int i = 0; i < n; ++i) scanf("%s", B[i]);

    for (zx = 0; zx < n; ++zx) {
        for (zy = 0; zy < n; ++zy)
            if (A[zx][zy] == 'Z') break;
        if (zy != n) break;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) id[i][j] = ++tot;

    S = 2 * tot + 1;
    T = S + 1;

    bfsFromZ();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (A[i][j] > '0' && A[i][j] <= '9') {
                addEdge(S, id[i][j], A[i][j] - '0');
                buildLinks(i, j, id[i][j]);
            }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (B[i][j] > '0' && B[i][j] <= '9')
                addEdge(id[i][j] + tot, T, B[i][j] - '0');

    printf("%d\n", maxflow());
    return 0;
}
